# Surah Al-Anfal (chapter 8) — part 3: ayat 19-28 (IDs 1179-1188)
SURAH = 8

ENTRIES = {
1179: (
"اگر — تم — فتح — مانگتے تھے — تو — فتح — آ گئی — اور — اگر — تم — باز آ جاؤ — تو — یہ — تمہارے لیے — بہتر ہے — اور — اگر — تم — واپس لوٹو — تو — ہم — بھی واپس آئیں گے — اور — تمہاری — جماعتیں — تمہیں — کچھ فائدہ نہیں دیں گی — اگرچہ — وہ — بہت سی ہوں — اور — یہ کہ اللہ — مؤمنوں کے ساتھ ہے",
"""۱۔ فتح — کافروں کے لیے — فیصلہ ہے۔
۲۔ ’’إِن تَسْتَفْتِحُوا فَقَدْ جَاءَكُمُ الْفَتْحُ وَإِن تَنتَهُوا فَهُوَ خَيْرٌ لَّكُمْ وَإِن تَعُودُوا نَعُدْ وَلَن تُغْنِيَ عَنكُمْ فِئَتُكُمْ شَيْئًا وَلَوْ كَثُرَتْ وَأَنَّ اللَّهَ مَعَ الْمُؤْمِنِينَ‘‘ — اگر — تم — فتح — مانگتے تھے — تو — فتح — آ گئی — اور — اگر — تم — باز آ جاؤ — تو — یہ — تمہارے لیے — بہتر ہے — اور — اگر — تم — واپس لوٹو — تو — ہم — بھی واپس آئیں گے — اور — تمہاری — جماعتیں — تمہیں — کچھ فائدہ نہیں دیں گی — اگرچہ — وہ — بہت سی ہوں — اور — یہ کہ اللہ — مؤمنوں کے ساتھ ہے — یعنی کافروں کو — فتح کی خواہش پر — فیصلہ مل گیا — اب — اگر — باز آ جائیں — بہتر ہے۔
۳۔ عملی سبق: حق پر قائم رہو؛ جماعتیں — اللہ کے فیصلے کو نہیں بدلیں گی۔"""
),
1180: (
"اے ایمان والو — اللہ اور اس کے رسولؐ کی اطاعت کرو — اور — اس — سے منہ نہ موڑو — جب کہ — تم — سن رہے ہو",
"""۱۔ اللہ اور رسولؐ کی اطاعت — لازم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَرَسُولَهُ وَلَا تَوَلَّوْا عَنْهُ وَأَنتُمْ تَسْمَعُونَ‘‘ — اے ایمان والو — اللہ اور اس کے رسولؐ کی اطاعت کرو — اور — اس — سے منہ نہ موڑو — جب کہ — تم — سن رہے ہو — یعنی اللہ اور رسولؐ کے حکم کے سامنے — سننا اور اطاعت — لازم ہے۔
۳۔ عملی سبق: رسولؐ کے حکم کو — کان لگا کر سنو اور — مانو۔"""
),
1181: (
"اور — ان کی طرح — مت بنو — جنہوں — نے کہا — ہم نے سنا — حالانکہ — وہ — نہیں سنتے",
"""۱۔ ظاہری سماعت — باطنی قبولیت کے بغیر۔
۲۔ ’’وَلَا تَكُونُوا كَالَّذِينَ قَالُوا سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ‘‘ — اور — ان کی طرح — مت بنو — جنہوں — نے کہا — ہم نے سنا — حالانکہ — وہ — نہیں سنتے — یعنی صرف زبان سے کہنا — سنا کافی نہیں — دل سے قبول کرنا — ضروری ہے۔
۳۔ عملی سبق: سننے کے ساتھ — عمل — بھی لازم ہے۔"""
),
1182: (
"بے شک — اللہ — کے نزدیک — سب — جانوروں — سے برے — بہرے گونگے — ہیں جو — نہیں سمجھتے",
"""۱۔ بہرے گونگے لوگ — جو نہیں سمجھتے — سب سے برے۔
۲۔ ’’إِنَّ شَرَّ الدَّوَابِّ عِندَ اللَّهِ الصُّمُّ الْبُكْمُ الَّذِينَ لَا يَعْقِلُونَ‘‘ — بے شک — اللہ — کے نزدیک — سب — جانوروں — سے برے — بہرے گونگے — ہیں جو — نہیں سمجھتے — یعنی جو لوگ — نہ سنتے ہیں نہ کہتے ہیں نہ — عقل استعمال کرتے ہیں — اللہ کے نزدیک سب سے برے ہیں۔
۳۔ عملی سبق: عقل اور سماعت — اللہ کی نعمتیں ہیں؛ انہیں استعمال کرو۔"""
),
1183: (
"اور — اگر — اللہ — ان — میں — کوئی بھلائی جانتا — تو — انہیں سناتا — اور — اگر — وہ انہیں سنانا — تو وہ — منہ — موڑ کر — روگردانی — کرتے",
"""۱۔ ان کے اندر بھلائی — نہیں — اس لیے — اللہ انہیں حق سناتا نہیں۔
۲۔ ’’وَلَوْ عَلِمَ اللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا وَّهُم مُّعْرِضُونَ‘‘ — اور — اگر — اللہ — ان — میں — کوئی بھلائی جانتا — تو — انہیں سناتا — اور — اگر — وہ انہیں سنانا — تو وہ — منہ — موڑ کر — روگردانی — کرتے — یعنی بھلائی نہ ہونے کی وجہ سے — نہ تو — وہ — حق سنتے ہیں — اور — اگر سنایا جائے — تب بھی — منہ موڑ لیتے ہیں۔
۳۔ عملی سبق: دل کی پاکیزگی — حق سننے کی کلید ہے۔"""
),
1184: (
"اے ایمان والو — اللہ — اور رسولؐ — کی پکار کا جواب دو — جب — وہ — تمہیں — ایسی چیز کی طرف — بلائیں — جو — تمہیں — زندگی دے — اور — جان لو — کہ — اللہ — آدمی کے — اور اس کے دل کے درمیان — حائل ہوتا ہے — اور — یہ کہ — تم — اس — کی طرف — اکٹھے کیے جاؤ گے",
"""۱۔ رسولؐ کی دعوت — زندگی۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ وَاعْلَمُوا أَنَّ اللَّهَ يَحُولُ بَيْنَ الْمَرْءِ وَقَلْبِهِ وَأَنَّهُ إِلَيْهِ تُحْشَرُونَ‘‘ — اے ایمان والو — اللہ — اور رسولؐ — کی پکار کا جواب دو — جب — وہ — تمہیں — ایسی چیز کی طرف — بلائیں — جو — تمہیں — زندگی دے — اور — جان لو — کہ — اللہ — آدمی کے — اور اس کے دل کے درمیان — حائل ہوتا ہے — اور — یہ کہ — تم — اس — کی طرف — اکٹھے کیے جاؤ گے — یعنی دعوتِ رسول — روحانی زندگی کا وسیلہ ہے؛ اللہ — انسان اور دل کے درمیان — حائل ہونے کی قدرت رکھتا ہے۔
۳۔ عملی سبق: رسولؐ کی دعوت — فوراً قبول کرو؛ اپنی موت کو — ہمیشہ یاد رکھو۔"""
),
1185: (
"اور — وہ — آفت — سے — ہوشیار رہو — جو — صرف — ان لوگوں کو نہیں پہنچے گی — جنہوں نے — تم — میں سے — ظلم کیا — اور — جان لو — کہ — اللہ — سخت عذاب دینے والا ہے",
"""۱۔ اجتماعی آفت — سب پر — حتیٰ کہ نیک لوگوں پر بھی۔
۲۔ ’’وَاتَّقُوا فِتْنَۃً لَّا تُصِيبَنَّ الَّذِينَ ظَلَمُوا مِنكُمْ خَاصَّۃً وَاعْلَمُوا أَنَّ اللَّهَ شَدِيدُ الْعِقَابِ‘‘ — اور — وہ — آفت — سے — ہوشیار رہو — جو — صرف — ان لوگوں کو نہیں پہنچے گی — جنہوں نے — تم — میں سے — ظلم کیا — اور — جان لو — کہ — اللہ — سخت عذاب دینے والا ہے — یعنی عمومی آفت — — ظالم اور مظلوم — دونوں کو — آ لیتی ہے۔
۳۔ عملی سبق: ظلم کو روکنا — سب کی ذمہ داری ہے؛ خاموشی — سب کو — آفت میں لے جا سکتی ہے۔"""
),
1186: (
"اور — یاد کرو — جب — تم — تھوڑے تھے — اور — زمین میں — کمزور سمجھے جاتے تھے — تمہیں — خوف تھا کہ — لوگ — تمہیں — اچک لے جائیں گے — پس — اسی — نے — تمہیں — پناہ دی — اور — اپنی مدد سے — تمہاری تائید کی — اور — تمہیں — پاکیزہ چیزوں — سے — روزی دی — شاید — تم — شکر کرو",
"""۱۔ ہجرت اور بدر — دونوں صورتوں میں — اللہ کی مدد کی یاد۔
۲۔ ’’وَاذْكُرُوا إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِي الْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ النَّاسُ فَآوَاكُمْ وَأَيَّدَكُم بِنَصْرِهِ وَرَزَقَكُم مِّنَ الطَّيِّبَاتِ لَعَلَّكُمْ تَشْكُرُونَ‘‘ — اور — یاد کرو — جب — تم — تھوڑے تھے — اور — زمین میں — کمزور سمجھے جاتے تھے — تمہیں — خوف تھا کہ — لوگ — تمہیں — اچک لے جائیں گے — پس — اسی — نے — تمہیں — پناہ دی — اور — اپنی مدد سے — تمہاری تائید کی — اور — تمہیں — پاکیزہ چیزوں — سے — روزی دی — شاید — تم — شکر کرو — یعنی مکی دور میں — مسلمانوں کی — کمزور حالت — اور اللہ کی پناہ — واضح ہے۔
۳۔ عملی سبق: اپنی کمزور حالت — یاد رکھو؛ شکر کرو۔"""
),
1187: (
"اے ایمان والو — اللہ — اور رسولؐ — سے — دھوکہ مت کرو — اور — اپنی — امانت — سے — خود — دھوکہ مت کرو — جب کہ — تم — جانتے ہو",
"""۱۔ اللہ اور رسولؐ سے دھوکہ — بہت بڑا جرم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنتُمْ تَعْلَمُونَ‘‘ — اے ایمان والو — اللہ — اور رسولؐ — سے — دھوکہ مت کرو — اور — اپنی — امانت — سے — خود — دھوکہ مت کرو — جب کہ — تم — جانتے ہو — یعنی اللہ اور رسولؐ سے دھوکہ — یعنی ایمان کا دعویٰ کر کے — خلافِ ایمان عمل — کرنا۔
۳۔ عملی سبق: امانت — ہر صورت میں — پورا کرو۔"""
),
1188: (
"اور — جان لو — کہ — تمہارے مال — اور تمہارے بچے — ایک — آزمائش ہیں — اور — یہ کہ — اللہ — کے پاس — عظیم اجر — ہے",
"""۱۔ مال و اولاد — آزمائش — اور اس کی قیمت۔
۲۔ ’’وَاعْلَمُوا أَنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَۃٌ وَأَنَّ اللَّهَ عِندَهُ أَجْرٌ عَظِيمٌ‘‘ — اور — جان لو — کہ — تمہارے مال — اور تمہارے بچے — ایک — آزمائش ہیں — اور — یہ کہ — اللہ — کے پاس — عظیم اجر — ہے — یعنی مال و اولاد — آزمائش — ہیں؛ اللہ — ان سے — اوپر اٹھنے والوں کے لیے — عظیم اجر — رکھتا ہے۔
۳۔ عملی سبق: مال و اولاد — کو — ایسی حد تک — مت رکھو — کہ وہ — اللہ کی راہ سے — روک دیں۔"""
),
}
